static int fl_write(uint32_t off, const uint8_t *src_ram, uint32_t n)
{
    uint32_t took;
    while (n) {
        uint32_t chunk = 256u - (off & 0xFFu);
        int rc;
        uint32_t f;
        if (chunk > n) chunk = n;
        f = irq_save();
        rc = FL_FAR(fl_prog_ram)(off, src_ram, chunk, &took);
        irq_restore(f);
        if (rc) return rc;
        off += chunk; src_ram += chunk; n -= chunk;
    }
    return 0;
}

static int st_prog(uint32_t off, const void *src, uint32_t n)
{
    const uint8_t *s = src;
    uint32_t i;
    if (!FL_STORE_OK(off, n) || (off & 0xFFu) + n > 256u) {
        outside++;
        return -8;
    }
    progs++;
    for (i = 0; i < n; i++)
        nor[off + i] &= s[i];
    return 0;
}

/* one key's ends from x16 values, kept apart and in range */
static void sn_cal_put(sense_key_t *k, uint32_t f16, uint32_t c16)
{
    if (f16 < (SN_DBASE + 16u) << 4)
        f16 = (SN_DBASE + 16u) << 4;
    if (c16 > 1020u << 4)
        c16 = 1020u << 4;
    if (c16 < f16 + (SN_SPAN << 4)) {              /* too close: part them about the middle */
        uint32_t mid = (f16 + c16) / 2u;
        f16 = mid - (SN_SPAN << 3);
        c16 = mid + (SN_SPAN << 3);
    }
    k->f16 = f16;
    k->c16 = c16;
    k->dfloor = (uint16_t)(f16 >> 4);
    k->dceil = (uint16_t)(c16 >> 4);
}

