static int log_frame(const uint8_t *p, uint32_t n)
{
    char b[48], *q;
    int k;
    if (n < 3u || p[0] != 0x7Du || p[1] != 0x4Cu || p[2] != 0x47u)
        return 0;
    if (fm1_crash.magic == FM1_CRASH_MAGIC) {
        const uint32_t v[6] = {fm1_crash.count, fm1_crash.vec, fm1_crash.pc, fm1_crash.rets, fm1_crash.sp,
                               fm1_crash.uptime_ms};
        static const char *const L[6] = {"crash n ", " vec ", " pc ", " rets ", " sp ", " ms "};
        uint32_t i;
        q = b;
        for (i = 0; i < 3u; i++) {
            const char *l = L[i];
            while (*l)
                *q++ = *l++;
            hexs(q, v[i]);
            q += 8;
        }
        *q = 0;
        log_line_send(b);
        q = b;
        for (i = 3; i < 6u; i++) {
            const char *l = L[i] + 1;
            while (*l)
                *q++ = *l++;
            hexs(q, v[i]);
            q += 8;
            *q++ = ' ';
        }
        *q = 0;
        log_line_send(b);
        for (k = (int)FM1_CRASH_CTX_N - 1; k >= 0; k--) {   /* the registers at the last crashes, the oldest first */
            const fm1_crash_ctx_t *x = &fm1_crash_ctx[(fm1_crash.count - (uint32_t)k) % FM1_CRASH_CTX_N];
            uint32_t r, j;
            if (x->count != fm1_crash.count - (uint32_t)k || x->count == 0u)
                continue;                            /* (not one of them: an older run's, or never written) */
            q = b;
            for (j = 0; j < 8u; j++)
                *q++ = "regs n  "[j];
            hexs(q, x->count);
            q += 8;
            for (j = 0; j < 4u; j++)
                *q++ = " pc "[j];
            hexs(q, x->pc);
            q += 8;
            for (j = 0; j < 5u; j++)
                *q++ = " usp "[j];
            hexs(q, x->usp);
            log_line_send(b);
            for (r = 0; r < 16u; r += 4u) {
                q = b;
                *q++ = 'r';
                *q++ = (char)('0' + r / 10u);
                *q++ = (char)('0' + r % 10u);
                for (j = 0; j < 4u; j++) {
                    *q++ = ' ';
                    hexs(q, x->r[r + j]);
                    q += 8;
                }
                log_line_send(b);
            }
        }
    } else {
        log_line_send("no crash recorded");
    }
    if (wdt_stage) {
        static const char *const ST[7] = {"?", "?", "Bluetooth", "the app's loop", "USB", "a frame", "input"};
        char *q = b;
        const char *t = "last watchdog reset in ";
        while (*t)
            *q++ = *t++;
        t = ST[wdt_stage < 7u ? wdt_stage : 0];
        while (*t)
            *q++ = *t++;
        *q = 0;
        log_line_send(b);
    }
    for (k = (int)plat_ble_log_total() - 1; k >= 0; k--) {
        if (!plat_ble_log_line(k)[0])
            continue;                                /* (beyond what the log keeps) */
        log_line_send(plat_ble_log_line(k));
    }
    {
        extern uint32_t lock_max, lock_from;
        static const char *const L[5] = {"gap ", " late ", " tick ", "lock ", " from "};
        const uint32_t v[5] = {t5_gap_max, t5_late, t5_run_max, lock_max, lock_from};
        uint32_t i;
        q = b;
        for (i = 0; i < 5u; i++) {
            const char *l = L[i];
            if (i == 3u) {                           /* two lines: a frame holds ~40 characters */
                *q = 0;
                log_line_send(b);
                q = b;
            }
            while (*l)
                *q++ = *l++;
            hexs(q, v[i]);
            q += 8;
        }
        *q = 0;
        log_line_send(b);
        t5_gap_max = t5_late = t5_run_max = lock_max = 0;
    }
#if FM1B_BLE
    {
        extern uint32_t shim_off_max, shim_off_from;
        const char *l = "BT irqs off max us ";
        q = b;
        while (*l)
            *q++ = *l++;
        hexs(q, shim_off_max);
        q += 8;
        for (l = " from "; *l;)
            *q++ = *l++;
        hexs(q, shim_off_from);
        log_line_send(b);
        shim_off_max = 0;
    }
#endif
    log_line_send("end");
    return 1;
}

static void ota_jl_enc(uint8_t *p, uint32_t n)   /* UFW header cipher, key 0xFFFF */
{
    uint32_t k = 0xFFFFu;
    while (n--) {
        *p++ ^= (uint8_t)k;
        k = ((k << 1) ^ (k & 0x8000u ? 0x1021u : 0u)) & 0xFFFFu;
    }
}

static void rev_apply(void)                           /* the render, at a block's start */
{
    int i, type = st.rev_type;
    int16_t *p = fdn_buf;
    float rt = erk_room_seconds(type, st.rev_size);
    rev_on = type != ERK_REV_OFF;
    for (i = 0; i < NFDN; i++) {
        fdn_n[i] = type == ERK_REV_CHAMBER ? fdn_cham[i] : fdn_hall[i];
        fdn_line[i] = p;
        p += fdn_hall[i];
        fdn_pos[i] = 0;
        fdn_lp[i] = 0;
        /* 10^(-3 n / (fs rt)) / sqrt 8, Q14 */
        fdn_g[i] = rev_on ? (int32_t)(exp2_f(-3.0f * 3.3219281f * (float)fdn_n[i] / (22050.0f * rt)) * 5792.6f) : 0;
    }
    fdn_keep = 32768 - (type == ERK_REV_CHURCH ? 12500 : type == ERK_REV_HALL ? 15000 : 19000);   /* the damping */
    pre_n = type == ERK_REV_CHURCH ? PRE_MAX : type == ERK_REV_HALL ? 330 : 150;
    pre_pos = 0;
    memset(fdn_buf, 0, sizeof fdn_buf);
    memset(ap_buf, 0, sizeof ap_buf);
    memset(pre_buf, 0, sizeof pre_buf);
    p = ap_buf;
    for (i = 0; i < 4; i++) {
        ap_line[i] = p;
        p += ap_len[i];
        ap_pos[i] = 0;
    }
    rev_prev_l = rev_prev_r = 0;
}
